import{z as s,x as B,o as e,c as p,q as i,j as o,D as E,d as r,s as A,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"TE / TM 对比","description":"","frontmatter":{"title":"TE / TM 对比","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/te-tm-polarization.md","filePath":"litho/te-tm-polarization.md","lastUpdated":1791413859000}'),h={name:"litho/te-tm-polarization.md"};function m(d,a,T,c,u,D){const l=B("Mermaid");return e(),p("div",null,[a[2]||(a[2]=i('<h1 id="te-tm-对比" tabindex="-1">TE / TM 对比 <a class="header-anchor" href="#te-tm-对比" aria-label="Permalink to &quot;TE / TM 对比&quot;">​</a></h1><div class="epigraph"><p>矢量成像已经把 $|U|^2$ 换成能量沉积；还要问的是：同一对衍射级，电场平行于线还是躺在入射面里，条纹深度完全不同。</p><footer>—— 据 Flagello 高 NA 薄膜成像与 Yeung 矢量光刻模型对 s / p 干涉的讨论整理</footer></div><p><a href="/litho/vector-imaging">上一课</a>把高 \\(\\mathrm{NA}\\) 空中像升级为胶内能量沉积，并指出 TE（s）干涉深、TM（p）交叉项变弱。缺口是把这两偏振的<strong>成像差</strong>写成可对线栅使用的对比：同一节距、同一光瞳，只换偏振，NILS 差在哪。光瞳相位如何展开，留给<a href="/litho/zernike-aberrations">Zernike 像差</a>。产线 \\(k_1\\) 仍不在本课重写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课给出了矢量接口，但工艺上要选的是照明偏振：让密线走哪一个通道。约定相对线栅：TE 的电场平行于线条，两束电矢量近乎平行，干涉项 \\(\\mathbf{E}_1\\cdot\\mathbf{E}_2^*\\) 接近满额；TM 的电场在入射面内，随孔径角张开，夹角接近 \\(2\\theta\\) 时交叉项按余弦一类因子下降，暗区抬高，对比与 NILS 掉。缺口因此是这条对比差，而不是再推一遍「为什么标量不够」。</p><p>非偏振是两通道强度平均，密线得到中间值。要极值必须控偏振；只加大 \\(\\sigma\\) 填不满这笔账。</p><p><span class="marginnote">术语翻译：TE/TM 说的是光的「振动方向」。两束光要叠出深浅条纹，靠的是电场振动方向一致、步调一致。TE（s）偏振下两束电场几乎同向，像两根朝同一方向摆的跳绳，明暗拉得开；TM（p）偏振下两束电场各自朝不同方向倾，叠加出来的明暗自然变浅。</span></p><h3 id="对比差在最佳焦距就存在" tabindex="-1">对比差在最佳焦距就存在 <a class="header-anchor" href="#对比差在最佳焦距就存在" aria-label="Permalink to &quot;对比差在最佳焦距就存在&quot;">​</a></h3><p>离焦二次相位对两个通道都会乘，但 TM 损失在 \\(z=0\\) 已征收。把「浸没后焦深变差」全部写成 \\(k_2\\lambda/\\mathrm{NA}^2\\)，会把偏振税误记成轴向预算。Bossung 上，TM 主导的密线往往窗更瘦，即使光学焦深公式看起来只与 \\(\\mathrm{NA}\\) 有关。</p><p><span class="marginnote">线栅的 TE/TM 随取向转。水平密线与垂直密线要的「好偏振」正交。二维孔无法同时让两向都走纯 TE，这是接触孔比一维栅更早付矢量税的原因之一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把进入光瞳的每条光线分解为局部 s/p，在像面（或胶内）矢量叠加后再对源积分。Flagello 把高 NA 成像放进分层薄膜：界面上的 Fresnel 系数对 s/p 不同，驻波节点也不同。Yeung 的矢量核则把投影侧的偏振传递写进计算光刻。本课不推薄膜矩阵，只要求：报密线对比必须声明偏振；标量 \\(C\\) 是偏乐观的上界。</p><p>照明侧：线偏振、切向（azimuthal）偏振把能量推向 TE 通道，是浸没密线的常用附件。它不改 \\(\\mathrm{NA}/\\lambda\\) 截止，只改通带内两束的点积。</p><h3 id="浸没放大夹角" tabindex="-1">浸没放大夹角 <a class="header-anchor" href="#浸没放大夹角" aria-label="Permalink to &quot;浸没放大夹角&quot;">​</a></h3><p>\\(\\mathrm{NA}=n\\sin\\theta\\)。水把同样空间频率对应的 \\(\\theta\\) 做大，TM 退化来得更早。干式高 \\(\\mathrm{NA}\\) 已需小心；浸没必须默认矢量。本课不讲喷淋头，只钉夹角与点积。</p><p><span class="marginnote">「极化照明」几乎总是光源侧的偏振控制，不是把投影物镜改成偏振器。镀膜的 s/p 透过率差是二阶修正。</span></p>',16)),(e(),o(n,null,{default:E(()=>[A(l,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20VEC%5B%22%E7%9F%A2%E9%87%8F%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%20--%3E%20TE%5B%22TE%3A%20%E7%94%B5%E7%9F%A2%E9%87%8F%E5%B9%B3%E8%A1%8C%22%5D%0A%20%20VEC%20--%3E%20TM%5B%22TM%3A%20%E5%85%A5%E5%B0%84%E9%9D%A2%E5%86%85%E5%BC%A0%E5%BC%80%22%5D%0A%20%20TE%20--%3E%20HI%5B%22%E5%B9%B2%E6%B6%89%E6%B7%B1%20%2F%20NILS%20%E9%AB%98%22%5D%0A%20%20TM%20--%3E%20LO%5B%22%E4%BA%A4%E5%8F%89%E9%A1%B9%E5%BC%B1%20%2F%20%E6%9A%97%E5%8C%BA%E6%8A%AC%E9%AB%98%22%5D%0A%20%20HI%20--%3E%20POL%5B%22%E7%85%A7%E6%98%8E%E5%81%8F%E6%8C%AF%E9%80%89%E6%8B%A9%22%5D%0A%20%20LO%20--%3E%20POL%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"两束 TM 的电矢量随 \\(\\theta\\) 张开，相干叠加的调制相对 TE 下降；频率越靠近截止，\\(\\theta\\) 越大，密图形先死。这与离焦「高频先死」同构，只是本课的税在焦面就征收。掩模铬栅自身也会当弱偏振器，反射式吸收体还有取向差——那是掩模 3D 的缺口；本课的物是已经进光瞳的矢量场。",-1)),a[5]||(a[5]=t("p",null,"NILS 的定义不变，输入 \\(I\\) 换成能量沉积。上一课的 ILS 课仍然适用：TM 把阈值处的对数斜率削掉，剂量轴随之变脆。这就是为什么 SMO 目标里要写偏振，不能只优化标量 TCC。",-1)),a[6]||(a[6]=t("p",null,[t("span",{class:"marginnote"},"数字实例：TM 的交叉项大致按 \\(\\cos 2\\theta\\) 缩水。光线在光瞳边缘的孔径角 \\(\\theta=20^\\circ\\) 时，因子约 \\(\\cos 40^\\circ\\approx0.77\\)，还能用；\\(\\theta\\) 涨到 \\(45^\\circ\\)，\\(\\cos 90^\\circ=0\\)，TM 的干涉项整个消失。NA 越大边缘光线 \\(\\theta\\) 越大，密线条纹先从 TM 通道开始糊。")],-1)),(e(),o(n,null,{default:E(()=>[A(l,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%90%8C%E4%B8%80%E5%AF%B9%E8%A1%8D%E5%B0%84%E7%BA%A7%20%E5%AD%94%E5%BE%84%E8%A7%92%202%CE%B8%22%5D%20--%3E%20B%5B%22TE%3A%20%E4%B8%A4%E7%94%B5%E7%9F%A2%E9%87%8F%E4%BF%9D%E6%8C%81%E5%B9%B3%E8%A1%8C%22%5D%0A%20%20A%20--%3E%20C%5B%22TM%3A%20%E5%90%84%E8%87%AA%E5%81%8F%E5%90%91%E5%85%A5%E5%B0%84%E9%9D%A2%22%5D%0A%20%20B%20--%3E%20D%5B%22%E7%82%B9%E7%A7%AF%E6%8E%A5%E8%BF%91%E6%BB%A1%E9%A2%9D%20%E5%B9%B2%E6%B6%89%E6%B7%B1%22%5D%0A%20%20C%20--%3E%20E%5B%22%E7%82%B9%E7%A7%AF%E6%8C%89%20cos2%CE%B8%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20D%20--%3E%20F%5B%22%E6%9A%97%E5%8C%BA%E6%9B%B4%E9%BB%91%20NILS%20%E9%AB%98%22%5D%0A%20%20E%20--%3E%20G%5B%22%E6%9A%97%E5%8C%BA%E6%8A%AC%E9%AB%98%20%E5%AF%B9%E6%AF%94%E6%8E%89%22%5D%0A%20%20F%20--%3E%20H%5B%22%CE%B8%20%E8%B6%8A%E5%A4%A7%E4%B8%A4%E9%80%9A%E9%81%93%E5%B7%AE%E8%B7%9D%E8%B6%8A%E5%A4%A7%22%5D%0A%20%20G%20--%3E%20H%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">常见误区：初学者容易以为「切向偏振一开，所有图形都受益」。它只是把能量推向 TE 通道：对一维密线是红利，但二维孔和正交取向的线总有一个方向吃不到这份好处，甚至更差——所以偏振优化要跟着关键图形的取向走，不是全局开关。</span></p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到密线对比，高 \\(\\mathrm{NA}\\) 必须拆 TE/TM 或声明非偏振平均。Zernike 相位乘在每个偏振通道上，像差与矢量相乘，不互相替代。截止频率仍是 \\(\\mathrm{NA}/\\lambda\\)；矢量改的是同样进了瞳的两束还能黑多少。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是掩模 FDTD，也不是 EUV 多层膜偏振反射率表。不要引用未公开的机台偏振纯度指标。标量模型在低 \\(\\mathrm{NA}\\)、松节距上仍可用；切换判据是夹角与目标节距，不是品牌。切向偏振对孔类和正交密线有自己的代价，不是免费的「全部变 TE」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TE 电矢量平行于线，干涉深；TM 随 \\(\\theta\\) 张开，对比掉。</li><li>偏振税在最佳焦距已存在，与离焦叠加。</li><li>非偏振是平均；极值对比要控照明偏振。</li><li>取向正交的密线无法共用同一纯 TE。</li><li>像差在下一课进光瞳相位，与本课通道相乘。</li><li>出处：Flagello 等对高 NA 薄膜成像；Yeung 矢量光刻模型；Mack / Levinson 的产线表述。</li></ul>',7))])}const b=s(h,[["render",m]]);export{f as __pageData,b as default};
